code.cpp:
class Solution {
public:
    vector<int> frequencySort(vector<int>& nums) {
        int freq[201] = {0};
        for (int x : nums) freq[x + 100]++;
        vector<int> result;
        result.reserve(nums.size());
        for (int f = 1; f <= 100; f++) {
            for (int v = 100; v >= -100; v--) {
                if (freq[v + 100] == f) {
                    for (int i = 0; i < f; i++) result.push_back(v);
                }
            }
        }
        return result;
    }
};
